REQUIRED_IMPORTS = {
    "numpy": "numpy>=2.0,<3",
    "pandas": "pandas>=2.2,<3",
    "pyarrow": "pyarrow>=17",
    "scipy": "scipy>=1.14",
    "sklearn": "scikit-learn>=1.6",
    "psutil": "psutil>=6",
    "dotenv": "python-dotenv>=1",
    "xgboost": "xgboost>=3.0",
    "lightgbm": "lightgbm>=4.5",
    "catboost": "catboost>=1.2.8",
    "matplotlib": "matplotlib>=3.9",
    "networkx": "networkx>=3.3",
    "threadpoolctl": "threadpoolctl>=3.5",
}


def configure_utf8_stdio() -> None:
    """Keep redirected Windows logs from failing on Korean/status symbols."""
    for stream_name in ("stdout", "stderr"):
        stream = getattr(sys, stream_name, None)
        if stream is not None and hasattr(stream, "reconfigure"):
            try:
                stream.reconfigure(encoding="utf-8", errors="backslashreplace")
            except Exception:
                pass


def print_header(battle_mode: bool = False) -> None:
    print("=" * 78)
    print("CrashWatch TickerElite2H SINGLE — 종목별 독립 모델 2시간 풀로드")
    if battle_mode:
        print("- 배그 모드: CPU 4스레드 / GPU 완전 봉인 / 낮은 프로세스 우선순위")
        print("- CPU 모델 worker 1개 / 신규 상관분석 worker 0개")
    else:
        print("- Ryzen 9800X3D 16스레드 / RTX 5080 / RAM 32GB")
        print("- 하이브리드: GPU worker 1개 + CPU worker 3개 × 4스레드")
    print("- 종목별 float32 메모리맵으로 worker RAM 복사 최소화")
    print("- 커버리지보다 학습 가능한 종목의 개별 성능 우선")
    print("=" * 78)


def runtime_root() -> Path:
    if os.name == "nt":
        base = Path(os.environ.get("LOCALAPPDATA", Path.home() / "AppData" / "Local"))
    else:
        base = Path(os.environ.get("XDG_CACHE_HOME", Path.home() / ".cache"))
    return base / "CrashWatch" / "TickerElite2H" / APP_VERSION


def decode_payload() -> bytes:
    raw = base64.b85decode("".join(PAYLOAD_B85.split()).encode("ascii"))
    actual = hashlib.sha256(raw).hexdigest()
    if actual != PAYLOAD_SHA256:
        raise RuntimeError(f"내장 코드 무결성 오류: expected={PAYLOAD_SHA256}, actual={actual}")
    return raw


def ensure_runtime(force: bool = False) -> Path:
    root = runtime_root()
    marker = root / ".payload_sha256"
    if not force and marker.exists() and marker.read_text(encoding="utf-8").strip() == PAYLOAD_SHA256:
        return root
    print(f"[준비] 내장 실험 코드를 추출합니다: {root}")
    root.parent.mkdir(parents=True, exist_ok=True)
    temp_dir = Path(tempfile.mkdtemp(prefix="tickerelite2h_", dir=root.parent))
    try:
        archive = temp_dir / "payload.zip"
        archive.write_bytes(decode_payload())
        extracted = temp_dir / "runtime"
        extracted.mkdir()
        with zipfile.ZipFile(archive, "r") as handle:
            handle.extractall(extracted)
        (extracted / ".payload_sha256").write_text(PAYLOAD_SHA256, encoding="utf-8")
        if root.exists():
            shutil.rmtree(root, ignore_errors=True)
        extracted.replace(root)
    finally:
        shutil.rmtree(temp_dir, ignore_errors=True)
    return root


def script_dir() -> Path:
    try:
        return Path(__file__).resolve().parent
    except NameError:
        return Path.cwd()


def normalize_data_dir(path: Path) -> Path | None:
    path = path.expanduser().resolve()
    candidates = [path, path / "crashwatch_ai_data"]
    if path.is_file() and path.name == "training_dataset_finance11h.parquet":
        candidates.insert(0, path.parent.parent if path.parent.name == "development" else path.parent)
    for candidate in candidates:
        if (candidate / "development" / "training_dataset_finance11h.parquet").exists():
            return candidate
    return None


def saved_path_file() -> Path:
    return script_dir() / ".crashwatch_data_dir.txt"


def choose_folder_gui() -> Path | None:
    try:
        import tkinter as tk
        from tkinter import filedialog, messagebox
        root = tk.Tk()
        root.withdraw()
        root.attributes("-topmost", True)
        messagebox.showinfo(
            "CrashWatch 데이터 경로",
            "기존 crashwatch_ai_data 폴더를 선택하세요.\n"
            "development/training_dataset_finance11h.parquet가 필요합니다.",
            parent=root,
        )
        selected = filedialog.askdirectory(title="crashwatch_ai_data 폴더 선택", parent=root)
        root.destroy()
        return Path(selected) if selected else None
    except Exception:
        return None


def resolve_data_dir(cli_value: str | None) -> Path:
    candidates: list[Path] = []
    if cli_value:
        candidates.append(Path(cli_value))
    if os.environ.get("CRASHWATCH_DATA_DIR"):
        candidates.append(Path(os.environ["CRASHWATCH_DATA_DIR"]))
    saved = saved_path_file()
    if saved.exists():
        try:
            candidates.append(Path(saved.read_text(encoding="utf-8").strip()))
        except Exception:
            pass
    here = script_dir()
    cwd = Path.cwd()
    for base in [here, here.parent, cwd, cwd.parent, Path.home() / "Desktop", Path.home() / "Documents"]:
        candidates.extend([base / "crashwatch_ai_data", base])
    seen: set[str] = set()
    for candidate in candidates:
        key = str(candidate).lower()
        if key in seen:
            continue
        seen.add(key)
        normalized = normalize_data_dir(candidate)
        if normalized is not None:
            saved_path_file().write_text(str(normalized), encoding="utf-8")
            return normalized
    selected = choose_folder_gui()
    if selected is not None:
        normalized = normalize_data_dir(selected)
        if normalized is not None:
            saved_path_file().write_text(str(normalized), encoding="utf-8")
            return normalized
    while True:
        value = input("crashwatch_ai_data 경로를 입력하세요 (취소: q): ").strip().strip('"')
        if value.lower() in {"q", "quit", "exit"}:
            raise SystemExit(2)
        normalized = normalize_data_dir(Path(value))
        if normalized is not None:
            saved_path_file().write_text(str(normalized), encoding="utf-8")
            return normalized
        print("필수 parquet 파일을 찾지 못했습니다.")


def missing_packages() -> list[str]:
    return [spec for module, spec in REQUIRED_IMPORTS.items() if importlib.util.find_spec(module) is None]


def ensure_dependencies(skip_install: bool) -> None:
    missing = missing_packages()
    if not missing:
        print("[확인] 필수 Python 패키지가 준비되어 있습니다.")
        return
    print("[설치 필요] " + ", ".join(missing))
    if skip_install:
        raise RuntimeError("필수 패키지가 없습니다. --skip-install 옵션을 제거하세요.")
    command = [sys.executable, "-m", "pip", "install", "--upgrade", *missing]
    print("[설치] " + " ".join(command))
    subprocess.check_call(command)
    remaining = missing_packages()
    if remaining:
        raise RuntimeError("설치 후에도 불러오지 못한 패키지: " + ", ".join(remaining))


def set_environment(
    data_dir: Path,
    battle_mode: bool = False,
    *,
    longrun: bool = False,
    hours: float | None = None,
    hard_hours: float | None = None,
) -> None:
    os.environ["CRASHWATCH_DATA_DIR"] = str(data_dir)
    os.environ["CRASHWATCH_BATTLE_MODE"] = "1" if battle_mode else "0"
    os.environ["CRASHWATCH_LONGRUN"] = "1" if longrun else "0"
    os.environ["CUDA_VISIBLE_DEVICES"] = "-1" if battle_mode else "0"
    os.environ["CUDA_DEVICE_ORDER"] = "PCI_BUS_ID"
    os.environ["PYTHONUNBUFFERED"] = "1"
    os.environ["PYTHONHASHSEED"] = "17"
    os.environ["PYTHONUTF8"] = "1"
    if hours is not None:
        os.environ["CRASHWATCH_DEFAULT_HOURS"] = str(float(hours))
    if hard_hours is not None:
        os.environ["CRASHWATCH_HARD_MAX_HOURS"] = str(float(hard_hours))
    thread_limit = "4"
    for name in ["OMP_NUM_THREADS", "MKL_NUM_THREADS", "OPENBLAS_NUM_THREADS", "NUMEXPR_NUM_THREADS"]:
        os.environ[name] = thread_limit
    temp = data_dir / "ticker_elite2h" / "temp"
    temp.mkdir(parents=True, exist_ok=True)
    os.environ["JOBLIB_TEMP_FOLDER"] = str(temp)


def gpu_summary(sealed: bool = False) -> None:
    if sealed:
        print("[GPU] 배그 모드로 CUDA_VISIBLE_DEVICES를 비워 모델 GPU 사용을 봉인했습니다.")
        return
    try:
        output = subprocess.check_output(
            ["nvidia-smi", "--query-gpu=name,memory.total,driver_version,temperature.gpu", "--format=csv,noheader,nounits"],
            text=True,
            timeout=8,
        ).strip()
        print("[GPU] " + output)
    except Exception as exc:
        print(f"[경고] nvidia-smi 확인 실패: {exc}")
        print("CUDA 모델은 CPU로 몰래 대체되지 않고 실패로 기록됩니다.")


def print_status(data_dir: Path) -> int:
    result_dir = data_dir / "ticker_elite2h"
    registry = result_dir / "task_registry.sqlite"
    if not registry.exists():
        print("아직 작업대장이 없습니다.")
        return 0
    with sqlite3.connect(registry) as conn:
        rows = conn.execute("SELECT status,stage,COUNT(*) FROM tasks GROUP BY status,stage ORDER BY stage,status").fetchall()
    for status, stage, count in rows:
        print(f"{stage:18s} {status:10s} {count}")
    summary = result_dir / "run_summary.json"
    if summary.exists():
        print(summary.read_text(encoding="utf-8"))
    return 0


def request_stop(data_dir: Path) -> int:
    result_dir = data_dir / "ticker_elite2h"
    result_dir.mkdir(parents=True, exist_ok=True)
    (result_dir / "STOP_REQUESTED").write_text("requested from single launcher", encoding="utf-8")
    print("안전중지를 요청했습니다. 현재 학습 단위가 저장된 후 종료됩니다.")
    return 0


def run_experiment(runtime: Path, data_dir: Path, args: argparse.Namespace) -> int:
    gpu_summary(args.battle_mode)
    command = [sys.executable, str(runtime / "run_ticker_elite2h.py")]
    if args.dataset:
        command += ["--dataset", str(Path(args.dataset).expanduser().resolve())]
    if args.result_dir:
        command += ["--result-dir", str(Path(args.result_dir).expanduser().resolve())]
    print("[실행] " + " ".join(f'"{item}"' if " " in item else item for item in command))
    process = subprocess.Popen(command, cwd=runtime, env=os.environ.copy())
    try:
        return process.wait()
    except KeyboardInterrupt:
        print("\n[중단 요청] 현재 fold checkpoint 저장 후 종료를 요청합니다.")
        request_stop(data_dir)
        try:
            return process.wait(timeout=900)
        except subprocess.TimeoutExpired:
            process.terminate()
            return process.wait(timeout=60)


def parser() -> argparse.ArgumentParser:
    result = argparse.ArgumentParser(description="CrashWatch 종목별 독립 모델 2시간 풀로드 단일 실행기")
    result.add_argument("--data-dir", help="기존 crashwatch_ai_data 폴더")
    result.add_argument("--dataset", help="training_dataset_finance11h.parquet 직접 경로")
    result.add_argument("--result-dir", help="결과 폴더 직접 지정")
    result.add_argument("--skip-install", action="store_true")
    result.add_argument("--force-extract", action="store_true")
    result.add_argument("--extract-only", action="store_true")
    result.add_argument("--battle-mode", action="store_true", help="CPU 4스레드만 사용하고 GPU를 완전히 봉인")
    result.add_argument("--longrun", action="store_true", help="고정 validation-window 강건성 후속 실험을 추가")
    result.add_argument("--hours", type=float, help="목표 실행 시간")
    result.add_argument("--hard-hours", type=float, help="최대 실행 시간")
    action = result.add_mutually_exclusive_group()
    action.add_argument("--status", action="store_true")
    action.add_argument("--stop", action="store_true")
    return result


def main() -> int:
    configure_utf8_stdio()
    args = parser().parse_args()
    if args.hours is not None and args.hours <= 0:
        parser().error("--hours must be positive")
    if args.hard_hours is not None and args.hard_hours <= 0:
        parser().error("--hard-hours must be positive")
    if args.hours is not None and args.hard_hours is not None and args.hard_hours < args.hours:
        parser().error("--hard-hours must be greater than or equal to --hours")
    print_header(args.battle_mode)
    runtime = ensure_runtime(force=args.force_extract)
    print(f"[런타임] {runtime}")
    if args.extract_only:
        return 0
    data_dir = resolve_data_dir(args.data_dir)
    print(f"[데이터] {data_dir}")
    set_environment(
        data_dir, args.battle_mode, longrun=args.longrun,
        hours=args.hours, hard_hours=args.hard_hours,
    )
    if args.status:
        return print_status(data_dir)
    if args.stop:
        return request_stop(data_dir)
    ensure_dependencies(args.skip_install)
    code = run_experiment(runtime, data_dir, args)
    print("=" * 78)
    print(f"실행 종료 코드: {code}")
    print(f"결과 폴더: {data_dir / 'ticker_elite2h'}")
    desktop = Path.home() / "Desktop"
    packages = sorted(desktop.glob("CrashWatch_TickerElite2H_RESULTS_*.zip"), key=lambda path: path.stat().st_mtime) if desktop.exists() else []
    if packages:
        print(f"최신 연구 결과 ZIP: {packages[-1]}")
    print("=" * 78)
    return int(code)


if __name__ == "__main__":
    try:
        raise SystemExit(main())
    except Exception as exc:
        print("\n[실행 실패]")
        print(f"{type(exc).__name__}: {exc}")
        traceback.print_exc()
        if sys.stdin.isatty():
            try:
                input("Enter를 누르면 종료합니다...")
            except Exception:
                pass
        raise SystemExit(1)
